{"file_path":"src/application/consolidation-service.ts","content":"import type {
  CatalogRepository,
  ConsolidationSummary,
  ProductResolver,
  SellerEntry,
} from '../domain/contracts.js';

export class ConsolidationService {
  constructor(
    private readonly repository: CatalogRepository,
    private readonly resolver: ProductResolver,
  ) {}

  plan(
    entries: readonly SellerEntry[],
    options: { readonly dryRun: boolean; readonly databasePath: string; readonly elapsedMilliseconds: number },
  ): ConsolidationSummary {
    const counts = this.repository.withPlanningTransaction(() => this.resolver.plan(entries));
    return {
      version: '1',
      ...counts,
      elapsedMilliseconds: options.elapsedMilliseconds,
      dryRun: options.dryRun,
      databasePath: options.databasePath,
    };
  }
}
