{"file_path":"src/adapters/json-input-reader.ts","content":"import type { InputReader, SellerEntry } from '../domain/contracts.js';

export class JsonInputReader implements InputReader {
  read(bytes: string): readonly SellerEntry[] {
    const parsed: unknown = JSON.parse(bytes);
    if (!Array.isArray(parsed)) {
      throw new Error('Input must contain a JSON array.');
    }

    return parsed.map((row, index) => {
      if (typeof row !== 'object' || row === null) {
        throw new Error(`Input row ${index + 1} must be an object.`);
      }
      const candidate = row as Record<string, unknown>;
      if (typeof candidate.Id !== 'string' || typeof candidate.SellerName !== 'string') {
        throw new Error(`Input row ${index + 1} requires string Id and SellerName fields.`);
      }
      return { id: candidate.Id, sellerName: candidate.SellerName };
    });
  }
}
"}

{"file_path":"src/adapters/sqlite-catalog-repository.ts","content":"import { DatabaseSync } from 'node:sqlite';
import type { CatalogRepository } from '../domain/contracts.js';

/** Executes planning inside a rollback-only SQLite transaction. */
export class SqliteCatalogRepository implements CatalogRepository {
  constructor(private readonly databasePath: string) {}

  withPlanningTransaction<T>(operation: () => T): T {
    const database = new DatabaseSync(this.databasePath, { readOnly: true });
    try {
      database.exec('BEGIN');
      const result = operation();
      database.exec('ROLLBACK');
      return result;
    } catch (error) {
      try {
        database.exec('ROLLBACK');
      } catch {
        // The original database failure is the actionable diagnostic.
      }
      throw error;
    } finally {
      database.close();
    }
  }
}
"}

{"file_path":"src/adapters/deterministic-product-resolver.ts","content":"import type { ConsolidationCounts, ProductResolver, SellerEntry } from '../domain/contracts.js';

/**
 * SDD-001 only establishes the orchestration seam. Identity resolution and
 * mutation are deliberately deferred to SDD-004 and SDD-005.
 */
export class DeterministicProductResolver implements ProductResolver {
  plan(entries: readonly SellerEntry[]): ConsolidationCounts {
    const sellerEntries = new Set(entries.map((entry) => `${entry.sellerName}\u0000${entry.id}`));
    return {
      inputRows: entries.length,
      distinctSellerEntries: sellerEntries.size,
      matchedProducts: 0,
      insertedProducts: 0,
      insertedLinks: 0,
      alreadyPresentLinks: 0,
      rejectedRows: 0,
      ambiguousRows: 0,
    };
  }
}
"}

{"file_path":"src/adapters/reporter.ts","content":"import type { ConsolidationSummary, OutputFormat, Reporter } from '../domain/contracts.js';

export class SummaryReporter implements Reporter {
  render(summary: ConsolidationSummary, format: OutputFormat): string {
    if (format === 'json') {
      return `${JSON.stringify(summary)}\n`;
    }
    return [
      `Catalog consolidation ${summary.dryRun ? 'plan' : 'completed'}.`,
      `Rows: ${summary.inputRows}; distinct seller entries: ${summary.distinctSellerEntries}.`,
      `Matched: ${summary.matchedProducts}; inserts planned: ${summary.insertedProducts}; links planned: ${summary.insertedLinks}.`,
      `Rejected: ${summary.rejectedRows}; ambiguous: ${summary.ambiguousRows}.`,
    ].join('\n').concat('\n');
  }
}
"}

