{"file_path":"src/cli.ts","content":"import { readFileSync, statSync } from 'node:fs';
import { resolve } from 'node:path';
import { JsonInputReader } from './adapters/json-input-reader.js';
import { DeterministicProductResolver } from './adapters/deterministic-product-resolver.js';
import { SummaryReporter } from './adapters/reporter.js';
import { SqliteCatalogRepository } from './adapters/sqlite-catalog-repository.js';
import { ConsolidationService } from './application/consolidation-service.js';
import type { OutputFormat } from './domain/contracts.js';

interface CliOptions {
  readonly inputPath: string;
  readonly databasePath: string;
  readonly dryRun: boolean;
  readonly format: OutputFormat;
}

class CommandError extends Error {
  constructor(message: string, readonly exitCode: 2 | 3 | 4 = 2) {
    super(message);
  }
}

function usage(): string {
  return 'Usage: catalog-consolidate --input <products.json> --database <catalog.db> [--dry-run] [--format text|json]\n';
}

function parseArguments(arguments_: readonly string[]): CliOptions {
  let inputPath: string | undefined;
  let databasePath: string | undefined;
  let dryRun = false;
  let format: OutputFormat = 'text';

  for (let index = 0; index < arguments_.length; index += 1) {
    const argument = arguments_[index];
    if (argument === '--help' || argument === '-h') {
      throw new CommandError(usage());
    }
    if (argument === '--dry-run') {
      dryRun = true;
      continue;
    }
    if (argument === '--input' || argument === '--database' || argument === '--format') {
      const value = arguments_[index + 1];
      if (value === undefined || value.startsWith('--')) {
        throw new CommandError(`Missing value for ${argument}.\n${usage()}`);
      }
      index += 1;
      if (argument === '--input') inputPath = resolve(process.cwd(), value);
      if (argument === '--database') databasePath = resolve(process.cwd(), value);
      if (argument === '--format') {
        if (value !== 'text' && value !== 'json') {
          throw new CommandError(`Unsupported format: ${value}.\n${usage()}`);
        }
        format = value;
      }
      continue;
    }
    throw new CommandError(`Unknown option: ${argument}.\n${usage()}`);
  }

  if (inputPath === undefined || databasePath === undefined) {
    throw new CommandError(`Both --input and --database are required.\n${usage()}`);
  }
  return { inputPath, databasePath, dryRun, format };
}

function verifyFile(path: string, label: string): void {
  try {
    if (!statSync(path).isFile()) throw new Error('not a file');
  } catch {
    throw new CommandError(`${label} path is missing or unreadable: ${path}`);
  }
}

export function run(arguments_: readonly string[]): { readonly output: string; readonly exitCode: number } {
  let options: CliOptions;
  try {
    options = parseArguments(arguments_);
    verifyFile(options.inputPath, 'Input');
    verifyFile(options.databasePath, 'Database');
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Command validation failed.';
    return { output: message.endsWith('\n') ? message : `${message}\n`, exitCode: error instanceof CommandError ? error.exitCode : 2 };
  }

  try {
    const started = process.hrtime.bigint();
    const entries = new JsonInputReader().read(readFileSync(options.inputPath, 'utf8'));
    const summary = new ConsolidationService(
      new SqliteCatalogRepository(options.databasePath),
      new DeterministicProductResolver(),
    ).plan(entries, {
      dryRun: options.dryRun,
      databasePath: options.databasePath,
      elapsedMilliseconds: Number((process.hrtime.bigint() - started) / 1_000_000n),
    });
    return { output: new SummaryReporter().render(summary, options.format), exitCode: 0 };
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Database or planning failure.';
    return { output: `${message}\n`, exitCode: 4 };
  }
}

const result = run(process.argv.slice(2));
if (result.exitCode === 0) process.stdout.write(result.output);
else process.stderr.write(result.output);
process.exitCode = result.exitCode;
"}

